SELECT code FROM resource_node
 WHERE tenant_id = #{param1} AND id = #{param2}
   AND kind = #{param3}::resource_kind

SELECT id FROM workflow
 WHERE tenant_id = #{param1}
   AND id IN

    #{one}

SELECT id AS "id", ledger_id AS "ledgerId", run_id AS "runId",
       command_id AS "commandId", device_id AS "deviceId",
       method AS "method", state AS "state", attempts AS "attempts",
       created_at::text AS "createdAt", delivered_at::text AS "deliveredAt"
  FROM command_outbox
 WHERE tenant_id = #{param1}
 AND state = #{param2} 
 ORDER BY id DESC LIMIT #{param3}

SELECT id AS "id", run_id AS "runId", plate_barcode AS "plateBarcode",
       source_resource_id AS "sourceResourceId",
       target_resource_id AS "targetResourceId",
       status AS "status", error_code AS "errorCode",
       error_message AS "errorMessage", created_at::text AS "createdAt"
  FROM transfer_transaction
 WHERE tenant_id = #{param1}
 AND status = #{param2} 
 ORDER BY id DESC LIMIT #{param3}

SELECT id AS "id", plate_barcode AS "plateBarcode",
       resource_id AS "resourceId", evidence_type AS "evidenceType",
       run_id AS "runId", operator AS "operator", note AS "note",
       created_at::text AS "createdAt"
  FROM position_evidence
 WHERE tenant_id = #{param1}
 AND plate_barcode = #{param2} 
 ORDER BY id DESC LIMIT #{param3}

SELECT (params->'method_params')::text AS "mp", resource_id AS "resourceId"
  FROM workflow_node
 WHERE tenant_id = #{param1} AND workflow_id = #{param2} AND node_key = #{param3}

SELECT e.id AS "id", e.code AS "code", e.scope AS "scope", e.severity::text AS "severity", e.source AS "source", e.title AS "title", e.detail AS "detail", p.strategy::text AS "strategy", p.max_attempts AS "maxAttempts", p.params::text AS "params", p.priority AS "priority", p.enabled AS "enabled", p.scope AS "policyScope", (SELECT count(*) FROM error_occurrence o WHERE o.error_code_id = e.id) AS "occurrences", -- 这个码在**它自己的作用域**上有没有策略？没有 = 配置静默失效（M7） EXISTS (SELECT 1 FROM recovery_policy rp2 WHERE rp2.error_code_id = e.id AND rp2.enabled AND (rp2.scope = e.scope OR rp2.scope IS NULL)) AS "scopeCovered", (SELECT jsonb_agg(jsonb_build_object( 'id', rp.id, 'scope', rp.scope, 'strategy', rp.strategy::text, 'maxAttempts', rp.max_attempts, 'params', rp.params, 'priority', rp.priority, 'enabled', rp.enabled) ORDER BY rp.priority, rp.id)::text FROM recovery_policy rp WHERE rp.error_code_id = e.id) AS "policies" FROM error_code e LEFT JOIN LATERAL ( SELECT * FROM recovery_policy rp WHERE rp.error_code_id = e.id AND rp.enabled ORDER BY rp.priority, rp.id LIMIT 1) p ON true WHERE e.tenant_id = #{tenantId} AND e.deleted_at IS NULL AND e.severity::text = #{severity} AND e.scope = #{scope}
AND (e.code ILIKE #{keyword} OR e.title ILIKE #{keyword})
ORDER BY e.code

SELECT DISTINCT resource_id FROM workflow_node
 WHERE tenant_id = #{param1} AND workflow_id = #{param2}
   AND node_type = 'task' AND resource_id IS NOT NULL

SELECT method AS "method", p50_ms AS "p50Ms", p90_ms AS "p90Ms",
       min_ms AS "minMs", max_ms AS "maxMs", sample_count AS "sampleCount"
  FROM duration_model
 WHERE tenant_id = #{param1}
 ORDER BY sample_count DESC LIMIT #{param2}

